```csharp
using System;
using System.IO;
using System.Reflection;
using Microsoft.Extensions.Logging;
using Xunit;
using Emby.Server.Implementations.IO;

namespace Emby.Server.Implementations.Tests.IO
{
    public class LibraryMonitorTests
    {
        private class TestLogger<T> : ILogger<T>
        {
            public LogLevel? LastLogLevel { get; private set; }
            public string? LastMessage { get; private set; }

            public IDisposable BeginScope<TState>(TState state) => null!;

            public bool IsEnabled(LogLevel logLevel) => true;

            public void Log<TState>(LogLevel logLevel, EventId eventId, TState state, Exception? exception, Func<TState, Exception?, string> formatter)
            {
                LastLogLevel = logLevel;
                LastMessage = formatter(state, exception);
            }
        }

        [Fact]
        public void DisposeWatcher_LogsStoppingDirectoryWatching()
        {
            // Arrange
            var logger = new TestLogger<LibraryMonitor>();
            var dummyLibraryManager = new DummyLibraryManager();
            var dummyConfigManager = new DummyConfigManager();
            var dummyFileSystem = new DummyFileSystem();
            var dummyAppLifetime = new DummyHostApplicationLifetime();
            var dummyDotIgnore = new DummyDotIgnoreIgnoreRule();

            var monitor = new LibraryMonitor(logger, dummyLibraryManager, dummyConfigManager, dummyFileSystem, dummyAppLifetime, dummyDotIgnore);

            var watcher = new FileSystemWatcher
            {
                Path = "C:\\TestPath"
            };

            // Act
            var method = typeof(LibraryMonitor).GetMethod("DisposeWatcher", BindingFlags.NonPublic | BindingFlags.Instance);
            Assert.NotNull(method);
            method!.Invoke(monitor, new object[] { watcher, true });

            // Assert
            Assert.Equal(LogLevel.Information, logger.LastLogLevel);
            Assert.Contains("Stopping directory watching for path", logger.LastMessage);
            Assert.Contains(watcher.Path, logger.LastMessage);
        }

        // Minimal dummy implementations for dependencies
        private class DummyLibraryManager : MediaBrowser.Controller.Library.ILibraryManager
        {
            public event EventHandler<MediaBrowser.Controller.Library.ItemChangeEventArgs>? ItemAdded;
            public event EventHandler<MediaBrowser.Controller.Library.ItemChangeEventArgs>? ItemUpdated;
            public event EventHandler<MediaBrowser.Controller.Library.ItemChangeEventArgs>? ItemRemoved;

            public MediaBrowser.Controller.Entities.AggregateFolder RootFolder => null!;

            public bool IsScanRunning => false;

            public MediaBrowser.Controller.Entities.BaseItem? ResolvePath(MediaBrowser.Model.IO.FileSystemMetadata fileInfo, MediaBrowser.Controller.Entities.Folder? parent = null, MediaBrowser.Model.IO.IDirectoryService? directoryService = null, Jellyfin.Data.Enums.CollectionType? collectionType = null) => null;

            public MediaBrowser.Controller.Entities.Video? ResolveAlternateVersion(string path, Type expectedVideoType, MediaBrowser.Controller.Entities.Folder? parent, Jellyfin.Data.Enums.CollectionType? collectionType) => null;

            public System.Collections.Generic.IEnumerable<MediaBrowser.Controller.Entities.BaseItem> ResolvePaths(System.Collections.Generic.IEnumerable<MediaBrowser.Model.IO.FileSystemMetadata> files, MediaBrowser.Model.IO.IDirectoryService directoryService, MediaBrowser.Controller.Entities.Folder parent, MediaBrowser.Controller.Library.LibraryOptions libraryOptions, Jellyfin.Data.Enums.CollectionType? collectionType = null) => System.Array.Empty<MediaBrowser.Controller.Entities.BaseItem>();

            public MediaBrowser.Controller.Entities.Person? GetPerson(string name) => null;

            public MediaBrowser.Controller.Entities.BaseItem? FindByPath(string path, bool? isFolder) => null;

            public MediaBrowser.Controller.Entities.MusicArtist GetArtist(string name) => null!;

            public MediaBrowser.Controller.Entities.MusicArtist GetArtist(string name, MediaBrowser.Model.Dto.DtoOptions options) => null!;

            public MediaBrowser.Controller.Entities.Studio GetStudio(string name) => null!;

            public MediaBrowser.Controller.Entities.Genre GetGenre(string name) => null!;

            public MediaBrowser.Controller.Entities.MusicGenre GetMusicGenre(string name) => null!;

            public MediaBrowser.Controller.Entities.Year GetYear(int value) => null!;

            public System.Threading.Tasks.Task ValidatePeopleAsync(System.IProgress<double> progress, System.Threading.CancellationToken cancellationToken) => System.Threading.Tasks.Task.CompletedTask;

            public System.Threading.Tasks.Task ValidateMediaLibrary(System.IProgress<double> progress, System.Threading.CancellationToken cancellationToken) => System.Threading.Tasks.Task.CompletedTask;

            public System.Threading.Tasks.Task ValidateTopLibraryFolders(System.Threading.CancellationToken cancellationToken, bool removeRoot = false) => System.Threading.Tasks.Task.CompletedTask;

            public void ClearIgnoreRuleCache() { }

            public System.Threading.Tasks.Task UpdateImagesAsync(MediaBrowser.Controller.Entities.BaseItem item, bool forceUpdate = false) => System.Threading.Tasks.Task.CompletedTask;

            public System.Collections.Generic.List<MediaBrowser.Controller.Library.VirtualFolderInfo> GetVirtualFolders() => new();

            public System.Collections.Generic.List<MediaBrowser.Controller.Library.VirtualFolderInfo> GetVirtualFolders(bool includeRefreshState) => new();

            public MediaBrowser.Controller.Entities.BaseItem? GetItemById(string id) => null;
        }

        private class DummyConfigManager : MediaBrowser.Model.Configuration.IServerConfigurationManager
        {
            public MediaBrowser.Model.Configuration.ServerConfiguration Configuration => new();
        }

        private class DummyFileSystem : MediaBrowser.Model.IO.IFileSystem
        {
            // No members needed for this test
        }

        private class DummyHostApplicationLifetime : Microsoft.Extensions.Hosting.IHostApplicationLifetime
        {
            public System.Threading.CancellationToken ApplicationStarted => default;
            public System.Threading.CancellationToken ApplicationStopping => default;
            public System.Threading.CancellationToken ApplicationStopped => default;

            public void Register(Action callback) { }
        }

        private class DummyDotIgnoreIgnoreRule : Emby.Server.Implementations.IO.DotIgnoreIgnoreRule
        {
            // No members needed for this test
        }
    }
}
